for p in 1 2 3; do curl -s "https://api.github.com/orgs/open-vela/repos?per_page=100&page=$p" | python3 -c "
import json,sys
try: d=json.load(sys.stdin)
except: d=[]
for r in d: print(r['name'],'—',(r.get('description') or '')[:80])
"; done | grep -viE '^contest' | sort -u

