1	/****************************************************************************
2	 * board/contest_board/src/rk3576_mic.c
3	 *
4	 * AMP microphone demo: openvela owns a digital microphone on the 40-pin
5	 * header and streams the captured PCM to Linux over the rpmsg channel, where
6	 * it can be played back through the Linux-owned ES8388 codec/speaker.
7	 *
8	 *   microphone --PDM/I2S--> cpu3 (openvela) --rpmsg--> Linux /dev/ttyRPMSG0
9	 *
10	 * Two front ends are supported, picked at build time:
11	 *   CONFIG_RK3576_PDM  PDM1, for a PDM MEMS mic   (CLK GPIO4_A6/GPIO4_B0,
12	 *                                                  DATA GPIO4_B2)
13	 *   CONFIG_RK3576_SAI  SAI2, for an I2S MEMS mic  (SCLK/LRCK/SDI on
14	 *                                                  GPIO1_D1/D2/D3)
15	 * PDM wins if both are enabled.
16	 *
17	 * The same endpoint carries a tiny text protocol so the host can drive it:
18	 *
19	 *   echo MIC_START > /dev/ttyRPMSG0    start streaming raw PCM
20	 *   echo MIC_STOP  > /dev/ttyRPMSG0    stop streaming
21	 *   echo MIC_INFO  > /dev/ttyRPMSG0    reply with rate/format/health
22	 *   echo MIC_CH0   > /dev/ttyRPMSG0    take the other channel of the data
23	 *   echo MIC_CH1   > /dev/ttyRPMSG0      line (PDM only, see MIC_INFO peaks)
24	 *   anything else                      echoed back (link check)
25	 *
26	 * Recording from Linux is then just:
27	 *   stty -F /dev/ttyRPMSG0 raw -echo
28	 *   echo MIC_START > /dev/ttyRPMSG0; timeout 5 cat /dev/ttyRPMSG0 > mic.raw
29	 *   aplay -f S16_LE -r <hz> -c 1 mic.raw
30	 *
31	 * A second endpoint, "rpmsg-mic", carries the same PCM under the binary
32	 * protocol in rk3576_mic_proto.h: framed, sequenced and timestamped, with
33	 * the capabilities readable instead of assumed.  The Linux side of it is
34	 * the snd-rpmsg-mic kernel module, which turns it into an ALSA capture
35	 * card, so the microphone can be recorded with arecord like any other:
36	 *
37	 *   arecord -D hw:rpmsgmic,0 -f S16_LE -r 16000 -c 1 -d 5 mic.wav
38	 *
39	 * Both endpoints stay usable; the two sinks share one capture stream, and
40	 * the hardware runs whenever either of them asks for it.
41	 *
42	 * SPDX-License-Identifier: Apache-2.0
43	 ****************************************************************************/
44	
45	/****************************************************************************
46	 * Included Files
47	 ****************************************************************************/
48	
49	#include <nuttx/config.h>
50	
51	#include <stdio.h>
52	#include <string.h>
53	#include <time.h>
54	#include <unistd.h>
55	
56	#include <nuttx/kthread.h>
57	#include <nuttx/rpmsg/rpmsg.h>
58	
59	#include <arch/board/rk3576_mic_proto.h>
60	
61	#ifdef CONFIG_RK3576_PDM
62	#  include "rk3576_pdm.h"
63	#else
64	#  include "rk3576_sai.h"
65	#endif
66	
67	/****************************************************************************
68	 * Pre-processor Definitions
69	 ****************************************************************************/
70	
71	/* Front-end shim.  Both drivers expose the same shape, so the threads below
72	 * do not care which microphone is wired up.
73	 */
74	
75	#ifdef CONFIG_RK3576_PDM
76	#  define mic_hw_init()      rk3576_pdm_capture_init()
77	#  define mic_hw_start()     rk3576_pdm_start()
78	#  define mic_hw_stop()      rk3576_pdm_stop()
79	#  define mic_hw_read(b, n)  rk3576_pdm_read(b, n)
80	#  define mic_hw_overruns()  rk3576_pdm_overruns()
81	#  define MIC_SAMPLE_BITS    RK3576_PDM_SAMPLE_BITS
82	#  define MIC_CHANNELS       RK3576_PDM_CHANNELS
83	#  define MIC_FRONTEND       "pdm"
84	#else
85	#  define mic_hw_init()      rk3576_sai_capture_init()
86	#  define mic_hw_start()     rk3576_sai_start()
87	#  define mic_hw_stop()      rk3576_sai_stop()
88	#  define mic_hw_read(b, n)  rk3576_sai_read(b, n)
89	#  define mic_hw_overruns()  rk3576_sai_overruns()
90	#  define MIC_SAMPLE_BITS    RK3576_SAI_SAMPLE_BITS
91	#  define MIC_CHANNELS       RK3576_SAI_CHANNELS
92	#  define MIC_FRONTEND       "i2s"
93	#endif
94	
95	/* An rpmsg buffer is 512 bytes on this link (fixed by the Rockchip master),
96	 * so keep each PCM chunk comfortably below the usable payload.
97	 */
98	
99	#define MIC_CHUNK_SAMPLES   RPMSG_MIC_CHUNK_SAMPLES  /* 448 bytes of PCM */
100	
101	/* The capture FIFO holds only a couple of milliseconds, far less than a
102	 * single rpmsg_sendto() can take.  So the capture thread does nothing but
103	 * drain the FIFO into this ring, and a second thread ships it out; without
104	 * that split the FIFO overruns on every send.  1/2 second of slack.
105	 */
106	
107	#define MIC_RING_SAMPLES    8192
108	
109	/****************************************************************************
110	 * Private Data
111	 ****************************************************************************/
112	
113	static struct rpmsg_endpoint g_mic_ept;       /* "rpmsg-tty", text protocol */
114	static bool                  g_mic_bound;
115	static volatile bool         g_tty_want;      /* tty client asked to stream */
116	static volatile uint32_t     g_mic_peer;
117	
118	static struct rpmsg_endpoint g_snd_ept;       /* "rpmsg-mic", ALSA protocol */
119	static bool                  g_snd_bound;
120	static volatile bool         g_snd_want;      /* ALSA client asked to stream */
121	static volatile uint32_t     g_snd_peer;
122	static volatile uint32_t     g_snd_seq;
123	
124	static volatile bool         g_mic_running;   /* hardware is actually on */
125	static int                   g_mic_rate;
126	
127	static int16_t               g_mic_ring[MIC_RING_SAMPLES];
128	static volatile uint32_t     g_mic_head;   /* written by the capture thread */
129	static volatile uint32_t     g_mic_tail;   /* written by the sender thread  */
130	static volatile uint32_t     g_mic_dropped;
131	
132	/****************************************************************************
133	 * Private Functions
134	 ****************************************************************************/
135	
136	/****************************************************************************
137	 * Name: mic_want
138	 *
139	 * Description:
140	 *   The two sinks share one capture stream, so the hardware runs whenever
141	 *   either of them wants data.
142	 *
143	 ****************************************************************************/
144	
145	static inline bool mic_want(void)
146	{
147	  return g_tty_want || g_snd_want;
148	}
149	
150	/****************************************************************************
151	 * Name: mic_now_us
152	 *
153	 * Description:
154	 *   Slave monotonic clock in microseconds, stamped into every PCM chunk so
155	 *   the host can tell a late packet from a lost one.
156	 *
157	 ****************************************************************************/
158	
159	static uint64_t mic_now_us(void)
160	{
161	  struct timespec ts;
162	
163	  clock_gettime(CLOCK_MONOTONIC, &ts);
164	  return (uint64_t)ts.tv_sec * 1000000ull + (uint64_t)(ts.tv_nsec / 1000);
165	}
166	
167	/****************************************************************************
168	 * Name: rk3576_mic_snd_ept_cb
169	 *
170	 * Description:
171	 *   Host -> slave commands on the binary ("rpmsg-mic") endpoint.  Same rule
172	 *   as the text endpoint: only set flags here, the capture thread owns the
173	 *   hardware.
174	 *
175	 ****************************************************************************/
176	
177	static int rk3576_mic_snd_ept_cb(FAR struct rpmsg_endpoint *ept,
178	                                 FAR void *data, size_t len, uint32_t src,
179	                                 FAR void *priv)
180	{
181	  FAR const struct rpmsg_mic_hdr *hdr = data;
182	  struct
183	  {
184	    struct rpmsg_mic_hdr  hdr;
185	    struct rpmsg_mic_caps caps;
186	  }
187	  __attribute__((packed)) rsp;
188	
189	  if (len < sizeof(*hdr) || hdr->magic != RPMSG_MIC_MAGIC)
190	    {
191	      return 0;
192	    }
193	
194	  g_snd_peer = src;
195	
196	  switch (hdr->type)
197	    {
198	      case RPMSG_MIC_CMD_START:
199	        g_snd_seq  = 0;
200	        g_snd_want = true;
201	        break;
202	
203	      case RPMSG_MIC_CMD_STOP:
204	        g_snd_want = false;
205	        break;
206	
207	      case RPMSG_MIC_CMD_CHAN:
208	#ifdef CONFIG_RK3576_PDM
209	        if (hdr->arg <= 1)
210	          {
211	            rk3576_pdm_set_channel((int)hdr->arg);
212	          }
213	#endif
214	        break;
215	
216	      case RPMSG_MIC_CMD_CAPS:
217	        memset(&rsp, 0, sizeof(rsp));
218	        rsp.hdr.magic        = RPMSG_MIC_MAGIC;
219	        rsp.hdr.type         = RPMSG_MIC_RSP_CAPS;
220	        rsp.hdr.dropped      = g_mic_dropped;
221	        rsp.hdr.ts_us        = mic_now_us();
222	        rsp.caps.rate        = (uint32_t)(g_mic_rate > 0 ? g_mic_rate : 0);
223	        rsp.caps.bits        = MIC_SAMPLE_BITS;
224	        rsp.caps.channels    = MIC_CHANNELS;
225	        rsp.caps.chunk_samples = MIC_CHUNK_SAMPLES;
226	        rsp.caps.overruns    = mic_hw_overruns();
227	#ifdef CONFIG_RK3576_PDM
228	        rsp.caps.flags       = RPMSG_MIC_FLAG_PDM;
229	#endif
230	        rpmsg_sendto(ept, &rsp, sizeof(rsp), src);
231	        break;
232	
233	      default:
234	        break;
235	    }
236	
237	  return 0;
238	}
239	
240	/****************************************************************************
241	 * Name: rk3576_mic_ept_cb
242	 *
243	 * Description:
244	 *   Host -> slave commands.  Anything unrecognised is echoed back, which
245	 *   keeps the original link-check demo working.
246	 *
247	 *   Starting and stopping the hardware is left to the capture thread: the
248	 *   PDM start sequence has to wait out the microphone's wake-up and the
249	 *   decimation filter's settling time, which has no business happening in an
250	 *   rpmsg callback.
251	 *
252	 ****************************************************************************/
253	
254	static int rk3576_mic_ept_cb(FAR struct rpmsg_endpoint *ept, FAR void *data,
255	                             size_t len, uint32_t src, FAR void *priv)
256	{
257	  FAR const char *cmd = data;
258	  char info[128];
259	
260	  g_mic_peer = src;
261	
262	  if (len >= 9 && strncmp(cmd, "MIC_START", 9) == 0)
263	    {
264	      g_tty_want = true;
265	    }
266	  else if (len >= 8 && strncmp(cmd, "MIC_STOP", 8) == 0)
267	    {
268	      g_tty_want = false;
269	    }
270	  else if (len >= 7 && strncmp(cmd, "MIC_CH", 6) == 0 &&
271	           (cmd[6] == '0' || cmd[6] == '1'))
272	    {
273	#ifdef CONFIG_RK3576_PDM
274	      rk3576_pdm_set_channel(cmd[6] - '0');
275	#endif
276	    }
277	  else if (len >= 8 && strncmp(cmd, "MIC_INFO", 8) == 0)
278	    {
279	      int n;
280	
281	#ifdef CONFIG_RK3576_PDM
282	      uint16_t p0;
283	      uint16_t p1;
284	
285	      rk3576_pdm_peaks(&p0, &p1);
286	      n = snprintf(info, sizeof(info),
287	                   "MIC src=%s rate=%d bits=%d ch=%d ovr=%lu drop=%lu "
288	                   "peak0=%u peak1=%u fifomax=%lu\n",
289	                   MIC_FRONTEND, g_mic_rate, MIC_SAMPLE_BITS, MIC_CHANNELS,
290	                   (unsigned long)mic_hw_overruns(),
291	                   (unsigned long)g_mic_dropped,
292	                   (unsigned)p0, (unsigned)p1,
293	                   (unsigned long)rk3576_pdm_maxfifo());
294	#else
295	      n = snprintf(info, sizeof(info),
296	                   "MIC src=%s rate=%d bits=%d ch=%d ovr=%lu drop=%lu\n",
297	                   MIC_FRONTEND, g_mic_rate, MIC_SAMPLE_BITS, MIC_CHANNELS,
298	                   (unsigned long)mic_hw_overruns(),
299	                   (unsigned long)g_mic_dropped);
300	#endif
301	      rpmsg_sendto(ept, info, n, src);
302	    }
303	  else
304	    {
305	      /* Plain echo, as before */
306	
307	      rpmsg_sendto(ept, data, (int)len, src);
308	    }
309	
310	  return 0;
311	}
312	
313	/****************************************************************************
314	 * Name: rk3576_mic_capture_thread
315	 *
316	 * Description:
317	 *   Own the capture hardware: apply start/stop requests and drain the RX
318	 *   FIFO into the ring.  Neither front end has a usable FIFO-level
319	 *   interrupt, so this polls; that is affordable because this core runs
320	 *   nothing else, and it keeps the audio path free of the PL330 DMACs
321	 *   (which all belong to Linux).
322	 *
323	 ****************************************************************************/
324	
325	static int rk3576_mic_capture_thread(int argc, FAR char *argv[])
326	{
327	  int16_t burst[64];
328	
329	  for (; ; )
330	    {
331	      size_t got;
332	      size_t i;
333	
334	      if (mic_want() != g_mic_running)
335	        {
336	          if (mic_want())
337	            {
338	              g_mic_head = g_mic_tail = 0;
339	              mic_hw_start();
340	            }
341	          else
342	            {
343	              mic_hw_stop();
344	            }
345	
346	          g_mic_running = mic_want();
347	        }
348	
349	      if (!g_mic_running)
350	        {
351	          usleep(20 * 1000);
352	          continue;
353	        }
354	
355	      got = mic_hw_read(burst, sizeof(burst) / sizeof(burst[0]));
356	      if (got == 0)
357	        {
358	          /* Nothing yet; come back well before the FIFO could fill up. */
359	
360	          usleep(500);
361	          continue;
362	        }
363	
364	      for (i = 0; i < got; i++)
365	        {
366	          uint32_t next = (g_mic_head + 1) % MIC_RING_SAMPLES;
367	
368	          if (next == g_mic_tail)
369	            {
370	              g_mic_dropped++;    /* host is not draining fast enough */
371	              break;
372	            }
373	
374	          g_mic_ring[g_mic_head] = burst[i];
375	          g_mic_head = next;
376	        }
377	    }
378	
379	  return 0;
380	}
381	
382	static int rk3576_mic_send_thread(int argc, FAR char *argv[])
383	{
384	  /* The PCM sits behind the header in one buffer, so the binary path can
385	   * hand rpmsg a single framed packet without a second copy.
386	   */
387	
388	  static struct
389	  {
390	    struct rpmsg_mic_hdr hdr;
391	    int16_t              pcm[MIC_CHUNK_SAMPLES];
392	  }
393	  __attribute__((packed)) pkt;
394	
395	  for (; ; )
396	    {
397	      size_t n = 0;
398	
399	      if (!g_mic_running || (!g_mic_bound && !g_snd_bound))
400	        {
401	          usleep(20 * 1000);
402	          continue;
403	        }
404	
405	      while (n < MIC_CHUNK_SAMPLES && g_mic_tail != g_mic_head)
406	        {
407	          pkt.pcm[n++] = g_mic_ring[g_mic_tail];
408	          g_mic_tail = (g_mic_tail + 1) % MIC_RING_SAMPLES;
409	        }
410	
411	      if (n == 0)
412	        {
413	          usleep(2 * 1000);
414	          continue;
415	        }
416	
417	      if (g_snd_want && g_snd_bound)
418	        {
419	          pkt.hdr.magic   = RPMSG_MIC_MAGIC;
420	          pkt.hdr.type    = RPMSG_MIC_RSP_DATA;
421	          pkt.hdr.arg     = 0;
422	          pkt.hdr.seq     = g_snd_seq++;
423	          pkt.hdr.dropped = g_mic_dropped;
424	          pkt.hdr.ts_us   = mic_now_us();
425	
426	          rpmsg_sendto(&g_snd_ept, &pkt,
427	                       sizeof(pkt.hdr) + n * sizeof(int16_t), g_snd_peer);
428	        }
429	
430	      if (g_tty_want && g_mic_bound)
431	        {
432	          rpmsg_sendto(&g_mic_ept, pkt.pcm, n * sizeof(int16_t), g_mic_peer);
433	        }
434	    }
435	
436	  return 0;
437	}
438	
439	/****************************************************************************
440	 * Name: rk3576_mic_device_created / destroy
441	 ****************************************************************************/
442	
443	static void rk3576_mic_device_created(FAR struct rpmsg_device *rdev,
444	                                      FAR void *priv)
445	{
446	  if (strcmp("linux", rpmsg_get_cpuname(rdev)) == 0)
447	    {
448	      rpmsg_create_ept(&g_mic_ept, rdev, "rpmsg-tty",
449	                       RPMSG_ADDR_ANY, RPMSG_ADDR_ANY,
450	                       rk3576_mic_ept_cb, NULL);
451	      g_mic_bound = true;
452	
453	      rpmsg_create_ept(&g_snd_ept, rdev, RPMSG_MIC_EPT_NAME,
454	                       RPMSG_ADDR_ANY, RPMSG_ADDR_ANY,
455	                       rk3576_mic_snd_ept_cb, NULL);
456	      g_snd_bound = true;
457	    }
458	}
459	
460	static void rk3576_mic_device_destroy(FAR struct rpmsg_device *rdev,
461	                                      FAR void *priv)
462	{
463	  if (strcmp("linux", rpmsg_get_cpuname(rdev)) == 0)
464	    {
465	      g_mic_bound = false;
466	      g_tty_want  = false;
467	      rpmsg_destroy_ept(&g_mic_ept);
468	
469	      g_snd_bound = false;
470	      g_snd_want  = false;
471	      rpmsg_destroy_ept(&g_snd_ept);
472	    }
473	}
474	
475	/****************************************************************************
476	 * Public Functions
477	 ****************************************************************************/
478	
479	/****************************************************************************
480	 * Name: rk3576_mic_init
481	 *
482	 * Description:
483	 *   Bring up the capture front end and register the rpmsg endpoint that
484	 *   carries the PCM to Linux.  Replaces rk3576_rpmsg_echo_init() when a
485	 *   microphone front end is configured (the echo behaviour is preserved).
486	 *
487	 ****************************************************************************/
488	
489	int rk3576_mic_init(void)
490	{
491	  int ret;
492	
493	  /* A failure here must not cost us the rpmsg link: register the endpoint
494	   * anyway so the host still gets its echo channel and can read the reason
495	   * out of MIC_INFO (rate=0 means the front end did not come up).
496	   */
497	
498	  ret = mic_hw_init();
499	  if (ret > 0)
500	    {
501	      g_mic_rate = ret;
502	
503	      /* Capture must outrank the sender: the FIFO has no slack. */
504	
505	      kthread_create("amp_mic_cap", 200, 2048,
506	                     rk3576_mic_capture_thread, NULL);
507	      kthread_create("amp_mic_tx", 120, 2048,
508	                     rk3576_mic_send_thread, NULL);
509	    }
510	
511	  return rpmsg_register_callback(NULL,
512	                                 rk3576_mic_device_created,
513	                                 rk3576_mic_device_destroy,
514	                                 NULL, NULL);
515	}
516

