                PDM_PATH_MSK | PDM_VDW_MSK,
                PDM_RX_PATH_SEL(0, PDM_SDI_INDEX) | PDM_CKP_NORMAL |
                PDM_SJM_SEL_L | PDM_PATH0_EN | PDM_VDW(PDM_VDW_BITS));

